document.addEventListener('click',event=>{if(event.target.closest('.map-sheet-close')){selectedPlace.hidden=true;return}const brief=event.target.closest('[data-country-brief]');if(brief)window.openCountryBrief?.(brief.dataset.countryBrief)});
