function offlineMatches(query){const q=query.toLowerCase(),matches=[];(window.africanAtlas||[]).forEach(([country,,sites])=>{if(country.toLowerCase().includes(q))matches.push({country,name:country,type:'Country'});String(sites).split('·').map(site=>site.trim()).filter(site=>site.toLowerCase().includes(q)).forEach(name=>matches.push({country,name,type:'Pocketbook destination'}))});return matches.slice(0,8)}
function curatedPlaceMatch(query){const q=String(query||'').toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim(),places=[...(window.safariPlaces||[]),...(window.botswanaPlaces||[])];if(!q)return null;const exact=places.find(place=>place.name.toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim()===q);if(exact)return exact;const matches=places.filter(place=>{const name=place.name.toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim();return name.startsWith(`${q} `)||q.startsWith(`${name} `)});return matches.length===1?matches[0]:null}
